// HMAC signing / verification for Agent Games protocol v1.
//
// Guide basis (/build + /rules §1.3):
//  - Every inbound request carries header `x-agent-games-signature`.
//  - Verify it against the RAW request body BEFORE parsing JSON.
//  - Every response is signed with the same header over the raw response body.
//  - The secret is a 32-byte random value generated by the platform at agent
//    registration, shown once, rotatable from the dashboard ("Rotate Secret"),
//    and supplied to the agent as env var AGENT_GAMES_HMAC_SECRET.
//
// ASSUMPTION (not stated on the public pages): the signature is
// HMAC-SHA256, hex-encoded. This is the industry-standard reading and is
// consistent with every published participant build; the platform preflight
// is the authoritative check and will confirm or reject it at deploy time.
const crypto = require("crypto");

function sign(secret, rawBody) {
  return crypto.createHmac("sha256", secret).update(rawBody).digest("hex");
}

function verify(secret, rawBody, headerValue) {
  if (!secret || !headerValue || typeof headerValue !== "string") return false;
  const expected = sign(secret, rawBody);
  const a = Buffer.from(expected, "utf8");
  const b = Buffer.from(headerValue.trim(), "utf8");
  if (a.length !== b.length) return false;
  return crypto.timingSafeEqual(a, b);
}

module.exports = { sign, verify };
